import functools, logging, time
from dataclasses import dataclass

log = logging.getLogger(__name__)

@dataclass(frozen=True)
class Metrica:
    host: str
    lag: int | None
    status: str          # OK | ALERTA | PARADA

def retry(tentativas=3, pausa=5):
    def deco(fn):
        @functools.wraps(fn)
        def inv(*a, **k):
            for t in range(1, tentativas + 1):
                try:
                    return fn(*a, **k)
                except Exception as e:
                    log.warning("%s tentativa %d/%d: %s", fn.__name__, t, tentativas, e)
                    if t == tentativas:
                        raise
                    time.sleep(pausa)
        return inv
    return deco

@retry(tentativas=3)
def ler_lag(host: str) -> Metrica:
    lag = consultar(host)          # sua função do módulo 07
    status = "PARADA" if lag is None else ("ALERTA" if lag > 60 else "OK")
    return Metrica(host, lag, status)

from concurrent.futures import ThreadPoolExecutor, as_completed

def rodada(hosts, workers=10, timeout=15):
    resultados = {}
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futs = {ex.submit(ler_lag, h): h for h in hosts}
        for f in as_completed(futs, timeout=timeout * len(hosts)):
            h = futs[f]
            try:
                resultados[h] = f.result(timeout=timeout)
            except Exception as e:
                resultados[h] = Metrica(h, None, f"ERRO: {e}")
    return resultados

